/* Nexploria — expériences, lot 4/5.
   Chargé par js/app.js (qui définit EXPS, expRAF, addCtrl…) ; chaque lot s'exécute dans
   sa propre tâche pour ne pas bloquer le fil principal au chargement. */
// ══════════════════════════════════════════════
//  20 NOUVELLES EXPÉRIENCES — BATCH 4
// ══════════════════════════════════════════════

/* ── 75 : Bézier Curves ── */
EXPS.bezier={tag:'Mathématiques · Design',title:'Courbes de Bézier',hint:'Glissez les points de contrôle',
info:'<strong>Bézier</strong> (Pierre Bézier, 1962) : une courbe de degré n est définie par n+1 points de contrôle via les polynômes de Bernstein. B(t) = Σ bᵢ·Bᵢ,ₙ(t). Base de PostScript, SVG, TrueType et de tout dessin vectoriel.',
preview(c,g){const W=c.width,H=c.height;g.fillStyle='#080810';g.fillRect(0,0,W,H);const pts=[[W*.1,H*.8],[W*.3,H*.1],[W*.7,H*.1],[W*.9,H*.8]];g.strokeStyle='rgba(240,237,230,.15)';g.setLineDash([4,4]);g.lineWidth=.8;g.beginPath();pts.forEach(([x,y],i)=>i===0?g.moveTo(x,y):g.lineTo(x,y));g.stroke();g.setLineDash([]);pts.forEach(([x,y],i)=>{g.fillStyle=['#d63f0e','#5230cc','#5230cc','#2aaa7a'][i];g.beginPath();g.arc(x,y,5,0,Math.PI*2);g.fill()});g.strokeStyle='#d63f0e';g.lineWidth=2;g.beginPath();for(let i=0;i<=100;i++){const t=i/100;const mt=1-t;const x=mt*mt*mt*pts[0][0]+3*mt*mt*t*pts[1][0]+3*mt*t*t*pts[2][0]+t*t*t*pts[3][0];const y=mt*mt*mt*pts[0][1]+3*mt*mt*t*pts[1][1]+3*mt*t*t*pts[2][1]+t*t*t*pts[3][1];i===0?g.moveTo(x,y):g.lineTo(x,y)}g.stroke()},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height;let degree=3,showHull=true,showCasteljau=false,t=.5,animating=false,ta=0;let pts=[[W*.1,H*.8],[W*.25,H*.15],[W*.5,H*.05],[W*.75,H*.15],[W*.9,H*.8]];let dragging=-1;canvas.onmousedown=e=>{const mx=e.offsetX/canvas.offsetWidth*W,my=e.offsetY/canvas.offsetHeight*H;dragging=pts.findIndex(([x,y])=>Math.hypot(x-mx,y-my)<14)};canvas.onmouseup=()=>dragging=-1;canvas.onmousemove=e=>{if(dragging<0)return;pts[dragging]=[e.offsetX/canvas.offsetWidth*W,e.offsetY/canvas.offsetHeight*H];if(!animating)draw()};add('slider',{label:'Degré',min:1,max:6,val:degree,fn:v=>{degree=v;pts=Array.from({length:v+1},(_,i)=>[W*(.1+i/(v)*.8),i%2===0?H*.8:H*.15]);draw()}});add('btn',{label:'Enveloppe',ghost:true,fn:()=>{showHull=!showHull;if(!animating)draw()}});add('btn',{label:'Casteljau',ghost:true,fn:()=>{showCasteljau=!showCasteljau;if(!animating)draw()}});const ab=add('btn',{label:'▶ Animer',ghost:true,fn:()=>{animating=!animating;ab.textContent=animating?'⏸ Stop':'▶ Animer';if(animating)loop()}});
function deCasteljau(points,t){if(points.length===1)return points[0];const next=[];for(let i=0;i<points.length-1;i++)next.push([points[i][0]*(1-t)+points[i+1][0]*t,points[i][1]*(1-t)+points[i+1][1]*t]);return{pt:deCasteljau(next,t),intermediates:next}}function drawDC(points,t,depth=0){if(points.length<=1)return;const next=[];for(let i=0;i<points.length-1;i++){next.push([points[i][0]*(1-t)+points[i+1][0]*t,points[i][1]*(1-t)+points[i+1][1]*t])}ctx.strokeStyle=`hsla(${depth*60+200},75%,55%,.6)`;ctx.lineWidth=1;ctx.beginPath();next.forEach(([x,y],i)=>i===0?ctx.moveTo(x,y):ctx.lineTo(x,y));ctx.stroke();next.forEach(([x,y])=>{ctx.fillStyle=`hsl(${depth*60+200},75%,65%)`;ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill()});drawDC(next,t,depth+1)}
function draw(){const n=degree,p=pts.slice(0,n+1);ctx.fillStyle='#080810';ctx.fillRect(0,0,W,H);if(showHull){ctx.strokeStyle='rgba(240,237,230,.12)';ctx.setLineDash([4,4]);ctx.lineWidth=.8;ctx.beginPath();p.forEach(([x,y],i)=>i===0?ctx.moveTo(x,y):ctx.lineTo(x,y));ctx.stroke();ctx.setLineDash([])}if(showCasteljau)drawDC(p,ta%1||t);ctx.strokeStyle='#d63f0e';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<=200;i++){const tt=i/200;let x=0,y=0;const B=(n,k)=>{let b=1;for(let i=0;i<k;i++)b*=(n-i)/(i+1);return b};p.forEach(([px,py],k)=>{const b=B(n,k)*Math.pow(tt,k)*Math.pow(1-tt,n-k);x+=b*px;y+=b*py});i===0?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.stroke();p.forEach(([x,y],i)=>{ctx.fillStyle=i===0?'#2aaa7a':i===n?'#d63f0e':'#5230cc';ctx.beginPath();ctx.arc(x,y,6,0,Math.PI*2);ctx.fill()})}
function loop(){if(!animating)return;ta+=.005;draw();raf=expRAF(loop)}draw()}};

/* ── 76 : Forest Fire ── */
EXPS.forestfire={tag:'Biologie · Écologie',title:'Feu de Forêt Cellulaire',hint:'',
info:'<strong>Modèle forêt-feu</strong> (Bak, Chen & Tang, 1990) : un arbre brûle si un voisin brûle, sinon la foudre l\'allume avec probabilité f. Des états critiques auto-organisés émergent — loi de puissance sur la taille des incendies.',
preview(c,g){const S=5,cols=~~(c.width/S),rows=~~(c.height/S),grid=new Uint8Array(cols*rows);for(let i=0;i<cols*rows;i++)grid[i]=Math.random()<.6?1:0;g.fillStyle='#080810';g.fillRect(0,0,c.width,c.height);const pal=['#080810','#2f8a3a','#ff7a2a'];for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){if(grid[y*cols+x]){g.fillStyle=pal[grid[y*cols+x]];g.fillRect(x*S,y*S,S-1,S-1)}}},
setup(canvas,ctx,add){const S=5,cols=~~(canvas.width/S),rows=~~(canvas.height/S);let grid=new Uint8Array(cols*rows),f=0.0001,p=0.01,running=true;for(let i=0;i<cols*rows;i++)grid[i]=Math.random()<.6?1:0;const pal=['#080810','#2f8a3a','#ff7a2a'];add('slider',{label:'Prob. foudre f ×10⁴',min:0,max:50,val:1,fn:v=>f=v*.0001});add('slider',{label:'Prob. pousse p ×1000',min:1,max:100,val:10,fn:v=>p=v*.001});const pb=add('btn',{label:'⏸ Pause',fn:()=>{running=!running;pb.textContent=running?'⏸ Pause':'▶ Play';if(running)loop()}});add('btn',{label:'Reset',ghost:true,fn:()=>{for(let i=0;i<cols*rows;i++)grid[i]=Math.random()<.6?1:0;draw()}});
function step(){const next=new Uint8Array(cols*rows);for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const v=grid[y*cols+x];if(v===2)next[y*cols+x]=0;else if(v===1){let fire=false;[[0,-1],[0,1],[-1,0],[1,0]].forEach(([dx,dy])=>{const nx=(x+dx+cols)%cols,ny=(y+dy+rows)%rows;if(grid[ny*cols+nx]===2)fire=true});next[y*cols+x]=fire||Math.random()<f?2:1}else{next[y*cols+x]=Math.random()<p?1:0}}grid.set(next)}function draw(){ctx.fillStyle='#080810';ctx.fillRect(0,0,canvas.width,canvas.height);for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const v=grid[y*cols+x];if(v){ctx.fillStyle=pal[v];ctx.fillRect(x*S,y*S,S-1,S-1)}}}let fr=0;function loop(){if(!running)return;if(++fr%2===0){step();draw()}raf=expRAF(loop)}draw();loop()}};

/* ── 77 : Toric Knots ── */
EXPS.cliffordtorus={tag:'Mathématiques · Topologie',title:'Nœuds Toriques',hint:'',
info:'<strong>Nœud torique T(p,q)</strong> : une courbe qui fait p tours autour du tore dans une direction et q dans l\'autre. T(2,3) = nœud de trèfle, T(2,5) = nœud cinq-feuilles. Omniprésents en physique des cordes et en biologie (ADN).',
preview(c,g){const W=c.width,H=c.height;g.fillStyle='#080810';g.fillRect(0,0,W,H);const p=2,q=3,R=W*.28,r=W*.12,cx=W/2,cy=H/2;g.strokeStyle='#d63f0e';g.lineWidth=1.5;g.beginPath();for(let i=0;i<=600;i++){const t=i/600*Math.PI*2;const x=(R+r*Math.cos(q*t))*Math.cos(p*t),y=(R+r*Math.cos(q*t))*Math.sin(p*t),z=r*Math.sin(q*t);const px=cx+x*.7-z*.3,py=cy+y*.7-z*.2;i===0?g.moveTo(px,py):g.lineTo(px,py)}g.stroke()},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height;let p=2,q=3,R=Math.min(W,H)*.22,r=Math.min(W,H)*.11,t=0,animated=true,trail=[];const cx=W/2,cy=H/2;add('slider',{label:'p (tours axe)',min:1,max:8,val:2,fn:v=>{p=v;if(!animated)drawKnot()}});add('slider',{label:'q (tours tube)',min:1,max:9,val:3,fn:v=>{q=v;if(!animated)drawKnot()}});add('btn',{label:'Trèfle T(2,3)',ghost:true,fn:()=>{p=2;q=3;if(!animated)drawKnot()}});add('btn',{label:'T(3,4)',ghost:true,fn:()=>{p=3;q=4;if(!animated)drawKnot()}});add('btn',{label:'T(2,7)',ghost:true,fn:()=>{p=2;q=7;if(!animated)drawKnot()}});const ab=add('btn',{label:'⏸ Pause',ghost:true,fn:()=>{animated=!animated;ab.textContent=animated?'⏸ Pause':'▶ Play';if(animated)loop()}});
function proj(x,y,z,angle){const ca=Math.cos(angle),sa=Math.sin(angle);const x2=x*ca-y*sa,y2=x*sa+y*ca;const tilt=.55+.25*Math.sin(angle*.7),cb=Math.cos(tilt),sb=Math.sin(tilt);const y3=y2*cb-z*sb,z3=y2*sb+z*cb;const scale=1.3/(1+z3/(5*(R+r)));return{x:cx+x2*scale,y:cy+y3*scale,z:z3}}ctx.fillStyle='#080810';ctx.fillRect(0,0,W,H);
function drawKnot(){ctx.fillStyle='#080810';ctx.fillRect(0,0,W,H);const steps=Math.max(600,p*q*120),B=48,paths=Array.from({length:B},()=>new Path2D());let prev=null;for(let i=0;i<=steps;i++){const th=i/steps*Math.PI*2;const x=(R+r*Math.cos(q*th))*Math.cos(p*th),y=(R+r*Math.cos(q*th))*Math.sin(p*th),z=r*Math.sin(q*th);const pt=proj(x,y,z,t);if(prev){const k=Math.min(B-1,~~(i/steps*B));paths[k].moveTo(prev.x,prev.y);paths[k].lineTo(pt.x,pt.y)}prev=pt}ctx.lineWidth=2.2;ctx.lineCap='round';paths.forEach((pa,k)=>{ctx.strokeStyle=`hsl(${k/B*360},78%,58%)`;ctx.stroke(pa)});ctx.lineCap='butt';const ci=document.getElementById('canvas-info');if(ci)ci.textContent=`Nœud torique T(${p},${q})${gcdPQ(p,q)>1?' — p et q non premiers entre eux : entrelacs de '+gcdPQ(p,q)+' composantes':''}`}function gcdPQ(a,b){return b?gcdPQ(b,a%b):a}function loop(){if(!animated)return;t+=.008;drawKnot();raf=expRAF(loop)}drawKnot();loop()}};

/* ── 78 : Spiking Neurons ── */
EXPS.spiking={tag:'Biologie · Neurosciences',title:'Neurones à Impulsions',hint:'Cliquez pour stimuler un neurone',
info:'<strong>Modèle Integrate-and-Fire</strong> : τ·dV/dt = −V + R·I. Quand V atteint le seuil θ, le neurone tire (spike) et repart à 0. Des populations connectées forment des oscillateurs, des ondes et des états de mémoire.',
preview(c,g){const W=c.width,H=c.height;g.fillStyle='#080810';g.fillRect(0,0,W,H);const N=20,v=new Float32Array(N);for(let i=0;i<N;i++)v[i]=Math.random();const cx=W/2,cy=H/2,R=Math.min(W,H)*.35;for(let t=0;t<80;t++){for(let i=0;i<N;i++){v[i]+=.08+Math.random()*.04;for(let j=0;j<N;j++){if(i!==j)v[i]+=.01*(Math.random()<.3?v[j]*Math.cos((i-j)*.5)*.05:0)}if(v[i]>1){v[i]=0}}}for(let i=0;i<N;i++){const a=i/N*Math.PI*2,x=cx+R*Math.cos(a),y=cy+R*Math.sin(a);const fired=v[i]>0.8;g.fillStyle=fired?'#ffffff':`hsl(${240-v[i]*240},75%,${40+v[i]*25}%)`;g.beginPath();g.arc(x,y,fired?7:4,0,Math.PI*2);g.fill()}},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height,N=30;const v=new Float32Array(N),refrac=new Float32Array(N),spikes=[];const cx=W/2,cy=H/2,R=Math.min(W,H)*.38;const W_conn=Array.from({length:N},(_,i)=>Array.from({length:N},(_,j)=>i===j?0:(Math.random()<.3?(Math.random()>.5?.08:-.04):0)));let I_ext=1.05,tau=10;const flash=new Float32Array(N);add('slider',{label:'Courant I ×100',min:50,max:200,val:105,fn:v=>I_ext=v/100});add('slider',{label:'τ',min:5,max:30,val:10,fn:v=>tau=v});canvas.onclick=e=>{const mx=e.offsetX/canvas.offsetWidth*W,my=e.offsetY/canvas.offsetHeight*H;let best=-1,bd=Infinity;for(let i=0;i<N;i++){const a=i/N*Math.PI*2,x=cx+R*Math.cos(a),y=cy+R*Math.sin(a),d=Math.hypot(x-mx,y-my);if(d<bd){bd=d;best=i}}if(best>=0)v[best]=1.1};
function loop(){for(let s=0;s<3;s++){for(let i=0;i<N;i++){if(refrac[i]>0){refrac[i]--;continue}let input=I_ext+(Math.random()-.5)*.6;for(let j=0;j<N;j++)if(spikes[j])input+=W_conn[i][j]*4;v[i]+=(-v[i]+input)/tau;if(v[i]>=1){spikes[i]=true;flash[i]=1;v[i]=0;refrac[i]=5}else spikes[i]=false}}let nf=0;for(let i=0;i<N;i++)if(flash[i]>.9)nf++;const ci=document.getElementById('canvas-info');if(ci)ci.textContent=`I=${I_ext.toFixed(2)} — ${nf} neurone(s) viennent de tirer · clic : stimuler`;ctx.fillStyle='rgba(8,8,16,.15)';ctx.fillRect(0,0,W,H);for(let i=0;i<N;i++){const a=i/N*Math.PI*2,x=cx+R*Math.cos(a),y=cy+R*Math.sin(a);for(let j=i+1;j<N;j++){if(Math.abs(W_conn[i][j])>.01){const a2=j/N*Math.PI*2,x2=cx+R*Math.cos(a2),y2=cy+R*Math.sin(a2);ctx.strokeStyle=W_conn[i][j]>0?'rgba(42,170,122,.12)':'rgba(214,63,14,.1)';ctx.lineWidth=.5;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x2,y2);ctx.stroke()}}if(flash[i]>.05){ctx.fillStyle=`rgba(255,255,255,${flash[i]})`;ctx.beginPath();ctx.arc(x,y,6+flash[i]*8,0,Math.PI*2);ctx.fill();flash[i]*=.82}ctx.fillStyle=`hsl(${240-v[i]*240},80%,${45+v[i]*20}%)`;ctx.beginPath();ctx.arc(x,y,5+v[i]*4,0,Math.PI*2);ctx.fill()}raf=expRAF(loop)}loop()}};

/* ── 79 : Blackbody Radiation ── */
EXPS.radiation={tag:'Physique · Thermodynamique',title:'Corps Noir et Rayonnement',hint:'',
info:'<strong>Loi de Planck</strong> (1900) : B(ν,T) = 2hν³/c² · 1/(e^(hν/kT)−1). La loi de Wien donne le pic λ_max = b/T ≈ 2898 μm·K/T. C\'est la naissance de la mécanique quantique — Planck quantifia l\'énergie pour éviter la catastrophe ultraviolette.',
preview(c,g){const W=c.width,H=c.height;g.fillStyle='#080810';g.fillRect(0,0,W,H);const temps=[3000,4500,6000,8000];const colors=['#ff6a00','#ffaa44','#fff4e0','#c8d8ff'];temps.forEach((T,ti)=>{g.strokeStyle=colors[ti];g.lineWidth=1.2;g.beginPath();let max=0;const vals=[];for(let i=0;i<W;i++){const lam=(i/W*.9+.05)*3e-6,x=.014388/(lam*T),v=x>0.001?1/(Math.exp(Math.min(x,500))-1)/Math.pow(lam,5):0;vals.push(v);if(v>max)max=v}vals.forEach((v,i)=>{const y=H*.9-v/max*H*.8;i===0?g.moveTo(i,y):g.lineTo(i,y)});g.stroke()})},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height;let T=5778,showWien=true;const colors=['#ff4400','#ff8800','#ffcc44','#fff8d0','#c0d8ff','#8090ff'];function planck(lam,T){const h=6.626e-34,c=3e8,k=1.38e-23,x=h*c/(lam*k*T);return x>500?0:2*h*c*c/Math.pow(lam,5)/(Math.exp(x)-1)}add('slider',{label:'T (K)',min:1000,max:15000,val:T,fn:v=>{T=v;draw()}});add('btn',{label:'Soleil (5778K)',ghost:true,fn:()=>{T=5778;draw()}});add('btn',{label:'Ampoule (3000K)',ghost:true,fn:()=>{T=3000;draw()}});add('btn',{label:'Étoile bleue (15K)',ghost:true,fn:()=>{T=15000;draw()}});
function draw(){ctx.fillStyle='#080810';ctx.fillRect(0,0,W,H);const lams=Array.from({length:W},(_,i)=>(i/W*.9+.05)*3e-6);const vals=lams.map(l=>planck(l,T));const max=Math.max(...vals)||1;// Filled spectrum
for(let i=0;i<W;i++){const lam=lams[i]*1e9;let r,g2,b;if(lam<380){r=100;g2=0;b=200}else if(lam<450){r=~~((450-lam)/70*100);g2=0;b=255}else if(lam<495){r=0;g2=~~((lam-450)/45*255);b=255}else if(lam<570){r=~~((lam-495)/75*255);g2=255;b=~~((570-lam)/75*255)}else if(lam<620){r=255;g2=~~((620-lam)/50*255);b=0}else if(lam<700){r=255;g2=0;b=0}else{r=150;g2=0;b=0}const y=H*.88-vals[i]/max*H*.78;ctx.strokeStyle=`rgba(${r},${g2},${b},.5)`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(i,H*.88);ctx.lineTo(i,y);ctx.stroke()}ctx.strokeStyle='white';ctx.lineWidth=2;ctx.beginPath();vals.forEach((v,i)=>{const y=H*.88-v/max*H*.78;i===0?ctx.moveTo(i,y):ctx.lineTo(i,y)});ctx.stroke();if(showWien){const lam_max=.002898/T*1e9;const i_max=~~((lam_max/2700-.05)/.9*W);ctx.strokeStyle='rgba(255,255,255,.4)';ctx.setLineDash([4,4]);ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(i_max,0);ctx.lineTo(i_max,H);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='rgba(240,237,230,.7)';ctx.font='11px monospace';ctx.fillText(`T=${T}K  |  λmax=${~~lam_max}nm`,8,H-8)}}draw()}};

/* ── 80 : Texture CA ── */
EXPS.textureca={tag:'Art Génératif · Automates',title:'Textures par Automate',hint:'',
info:'<strong>Automates stochastiques</strong> : en ajoutant une probabilité aux transitions, on obtient des textures organiques. Chaque règle a une signature visuelle distincte — la base des procédures de génération de terrain dans les jeux vidéo.',
preview(c,g){const W=c.width,H=c.height,S=3,cols=~~(W/S),rows=~~(H/S);let grid=new Uint8Array(cols*rows);for(let i=0;i<cols*rows;i++)grid[i]=Math.random()<.5?1:0;for(let it=0;it<20;it++){const next=new Uint8Array(cols*rows);for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){let n=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(dx===0&&dy===0)continue;n+=grid[((y+dy+rows)%rows)*cols+(x+dx+cols)%cols]}next[y*cols+x]=n>=5?1:(n<=3?0:grid[y*cols+x])}grid=next}for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){g.fillStyle=grid[y*cols+x]?'#2a4a2a':'#080810';g.fillRect(x*S,y*S,S,S)}},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height,S=3,cols=~~(W/S),rows=~~(H/S);let grid=new Uint8Array(cols*rows),birth=5,survival_min=4,survival_max=8,pal=0;const palettes=[['#080810','#2a4a2a'],['#080810','#4a2a1a'],['#0a0820','#5230cc'],['#080810','#c47a15'],['#0a1020','#1456b0']];function init(){for(let i=0;i<cols*rows;i++)grid[i]=Math.random()<.45?1:0}init();add('slider',{label:'Naissance ≥',min:1,max:8,val:5,fn:v=>{birth=v;init();iter(40);draw()}});add('slider',{label:'Survie min',min:0,max:8,val:4,fn:v=>{survival_min=v;init();iter(40);draw()}});add('slider',{label:'Survie max',min:0,max:8,val:8,fn:v=>{survival_max=v;init();iter(40);draw()}});add('btn',{label:'Forêt',fn:()=>{birth=5;survival_min=4;survival_max=8;pal=0;init();iter(50);draw()}});add('btn',{label:'Lave',ghost:true,fn:()=>{birth=4;survival_min=3;survival_max=7;pal=1;init();iter(40);draw()}});add('btn',{label:'Galaxie',ghost:true,fn:()=>{birth=3;survival_min=2;survival_max=6;pal=2;init();iter(35);draw()}});add('btn',{label:'Nouveau',ghost:true,fn:()=>{init();iter(40);draw()}});
function iter(n){for(let it=0;it<n;it++){const next=new Uint8Array(cols*rows);for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){let nb=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(dx===0&&dy===0)continue;nb+=grid[((y+dy+rows)%rows)*cols+(x+dx+cols)%cols]}const v=grid[y*cols+x];next[y*cols+x]=v?((nb>=survival_min&&nb<=survival_max)?1:0):(nb>=birth?1:0)}grid=next}}function draw(){const [c0,c1]=palettes[pal];for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){ctx.fillStyle=grid[y*cols+x]?c1:c0;ctx.fillRect(x*S,y*S,S,S)}}init();iter(50);draw()}};

/* ── 81 : Audio Spectrum ── */
EXPS.audiospectrum={tag:'Physique · Acoustique',title:'Spectre et Harmoniques',hint:'',
info:'<strong>Synthèse additive</strong> : tout son peut être construit par superposition de sinusoïdes pures. Le timbre d\'un instrument = le profil de ses harmoniques. Fondement du synthétiseur, de la compression MP3 et de l\'analyse vocale.',
preview(c,g){const W=c.width,H=c.height;g.fillStyle='#080810';g.fillRect(0,0,W,H);const harmonics=[1,.6,.4,.25,.15,.1,.07,.05];harmonics.forEach((amp,i)=>{const bw=W/harmonics.length,x=i*bw+bw*.1,bh=amp*H*.7;g.fillStyle=`hsl(${i*30+10},75%,${45+amp*20}%)`;g.fillRect(x,H*.9-bh,bw*.8,bh)});let y_sum=0;g.strokeStyle='rgba(240,237,230,.3)';g.lineWidth=1;g.beginPath();for(let x=0;x<W;x++){const t=x/W*Math.PI*4;y_sum=harmonics.reduce((s,a,i)=>s+a*Math.sin((i+1)*t),0)/2;x===0?g.moveTo(x,H*.15+y_sum*H*.1):g.lineTo(x,H*.15+y_sum*H*.1)}g.stroke()},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height;let harmonics=[1,.6,.4,.25,.15,.1,.07,.05,.04,.03],waveform='sawtooth',t=0,playing=false;add('btn',{label:'Dent de scie',fn:()=>{waveform='sawtooth';harmonics=Array.from({length:10},(_,i)=>1/(i+1));draw()}});add('btn',{label:'Carré',ghost:true,fn:()=>{waveform='square';harmonics=Array.from({length:10},(_,i)=>i%2===0?1/(i+1):0);draw()}});add('btn',{label:'Triangle',ghost:true,fn:()=>{waveform='triangle';harmonics=Array.from({length:10},(_,i)=>i%2===0?Math.pow(-1,i/2)/Math.pow(i+1,2):0);draw()}});add('btn',{label:'Orgue',ghost:true,fn:()=>{harmonics=[1,.7,.5,.3,.1,.05,.02,.01,.005,.002];draw()}});const ab=add('btn',{label:'▶ Animer',ghost:true,fn:()=>{playing=!playing;ab.textContent=playing?'⏸ Stop':'▶ Animer';if(playing)loop()}});
function draw(){ctx.fillStyle='#080810';ctx.fillRect(0,0,W,H);// Bars
const bw=(W*.8)/harmonics.length;harmonics.forEach((a,i)=>{const bh=Math.abs(a)*H*.55,x=W*.1+i*bw,y=H*.72-bh;ctx.fillStyle=`hsl(${i*22+10},78%,${45+Math.abs(a)*20}%)`;ctx.fillRect(x,y,bw*.85,bh);ctx.fillStyle='rgba(240,237,230,.5)';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText(`H${i+1}`,x+bw*.4,H*.76)});// Waveform
ctx.strokeStyle='#d63f0e';ctx.lineWidth=2;ctx.beginPath();for(let x=0;x<W;x++){const tt=x/W*Math.PI*4+t;const y_s=harmonics.reduce((s,a,i)=>s+a*Math.sin((i+1)*tt),0);x===0?ctx.moveTo(x,H*.92-y_s*H*.12):ctx.lineTo(x,H*.92-y_s*H*.12)}ctx.stroke()}function loop(){if(!playing)return;t+=.04;draw();raf=expRAF(loop)}draw()}};

/* ── 82 : 3D Life ── */
EXPS.life3d={tag:'Informatique · Automates 3D',title:'Jeu de la Vie en 3D',hint:'',
info:'<strong>Automate 3D</strong> : le Jeu de la Vie étendu à 26 voisins cubiques. Différentes règles (B5678/S45678 = Coral, B45/S5 = Crystal) produisent des structures 3D stables, explosives ou cycliques.',
preview(c,g){const W=c.width,H=c.height;g.fillStyle='#080810';g.fillRect(0,0,W,H);const N=10,cells=new Set();for(let z=0;z<N;z++)for(let y=0;y<N;y++)for(let x=0;x<N;x++)if(Math.random()<.15)cells.add(`${x},${y},${z}`);const cx=W/2,cy=H*.4,sc=12,angle=.6;cells.forEach(k=>{const[x,y,z]=k.split(',').map(Number);const px=cx+(x-N/2)*sc-(z-N/2)*sc*Math.cos(angle),py=cy+(y-N/2)*sc*.7+(z-N/2)*sc*Math.sin(angle)*.5;g.fillStyle=`hsla(${x*25+y*15},70%,55%,.7)`;g.fillRect(px-3,py-3,6,6)})},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height,N=18;let cells=new Set(),birth=[4,5,6,7],survival=[5,6,7],step=0,angle=0,animAngle=true;function init(){step=0;cells.clear();for(let z=N/3;z<2*N/3;z++)for(let y=N/3;y<2*N/3;y++)for(let x=N/3;x<2*N/3;x++)if(Math.random()<.2)cells.add(`${x},${y},${z}`)}init();add('btn',{label:'Coral',fn:()=>{birth=[5,6,7,8];survival=[4,5,6,7,8];init()}});add('btn',{label:'Crystal',ghost:true,fn:()=>{birth=[4,5];survival=[5];init()}});add('btn',{label:'Éponge',ghost:true,fn:()=>{birth=[3];survival=[2,3,4,5];init()}});add('btn',{label:'Étape',ghost:true,fn:()=>{evolve();draw()}});const pb=add('btn',{label:'⏸ Pause',fn:()=>{animAngle=!animAngle;pb.textContent=animAngle?'⏸ Pause':'▶ Play';if(animAngle)loop()}});
function evolve(){const cnt=new Map();cells.forEach(k=>{const[x,y,z]=k.split(',').map(Number);for(let dz=-1;dz<=1;dz++)for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(dx===0&&dy===0&&dz===0)continue;const nx=x+dx,ny=y+dy,nz=z+dz;if(nx<0||nx>=N||ny<0||ny>=N||nz<0||nz>=N)continue;const nk=`${nx},${ny},${nz}`;cnt.set(nk,(cnt.get(nk)||0)+1)}});const next=new Set();cnt.forEach((n,k)=>{if(cells.has(k)){if(survival.includes(n))next.add(k)}else{if(birth.includes(n))next.add(k)}});cells=next;step++}function draw(){ctx.fillStyle='#080810';ctx.fillRect(0,0,W,H);const sc=Math.min(W,H)/(N*1.8),cx=W/2,cy=H*.45;const sorted=[...cells].map(k=>{const[x,y,z]=k.split(',').map(Number);return{x,y,z,d:z*Math.cos(angle)+x*Math.sin(angle)}}).sort((a,b)=>a.d-b.d);sorted.forEach(({x,y,z})=>{const px=cx+(x-N/2)*sc*Math.cos(angle)-(z-N/2)*sc*Math.sin(angle),py=cy+(y-N/2)*sc*.75+(z-N/2)*sc*Math.cos(angle)*.4+(x-N/2)*sc*Math.sin(angle)*.2;const hue=(x*20+y*15+z*25)%360;ctx.fillStyle=`hsla(${hue},72%,52%,.8)`;ctx.fillRect(px-sc*.45,py-sc*.45,sc*.9,sc*.9)});const ci=document.getElementById('canvas-info');if(ci)ci.textContent=`Step ${step} — ${cells.size} cellules vivantes`}let frame=0;function loop(){if(!animAngle)return;angle+=.008;if(++frame%20===0){evolve();if(cells.size===0)init()}draw();raf=expRAF(loop)}loop()}};

/* ── 83 : Potts/Ising Color ── */
EXPS.isingcolor={tag:'Physique · Art Génératif',title:'Ising Chromatique (Modèle de Potts)',hint:'',
info:'<strong>Modèle de Potts</strong> (Renfrey Potts, 1952) : généralisation d\'Ising à q états. Pour q=2 : Ising standard. Pour q≥3 : transition du 1er ordre. Les domaines colorés forment une peinture vivante autour de Tc.',
preview(c,g){const S=5,cols=~~(c.width/S),rows=~~(c.height/S),Q=6;const grid=new Uint8Array(cols*rows).map(()=>~~(Math.random()*Q));for(let it=0;it<60;it++){const i=~~(Math.random()*cols*rows),x=i%cols,y=~~(i/cols),s=grid[i];const nb=grid[y*cols+(x+1)%cols]+grid[y*cols+(x-1+cols)%cols]+grid[(y+1)%rows*cols+x]+grid[(y-1+rows)%rows*cols+x];const same=[[0,1],[-1,0],[0,-1],[1,0]].filter(([dx,dy])=>grid[((y+dy+rows)%rows)*cols+(x+dx+cols)%cols]===s).length;const ns=~~(Math.random()*Q);const nsame=[[0,1],[-1,0],[0,-1],[1,0]].filter(([dx,dy])=>grid[((y+dy+rows)%rows)*cols+(x+dx+cols)%cols]===ns).length;if(nsame>same||Math.random()<Math.exp((nsame-same)/2.5))grid[i]=ns}for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){g.fillStyle=`hsl(${grid[y*cols+x]/Q*360},70%,50%)`;g.fillRect(x*S,y*S,S-1,S-1)}},
setup(canvas,ctx,add){const S=4,cols=~~(canvas.width/S),rows=~~(canvas.height/S);let Q=6,T=.6,grid=new Uint8Array(cols*rows).map(()=>~~(Math.random()*Q)),step=0;add('slider',{label:'Q états',min:2,max:12,val:Q,fn:v=>{Q=v;grid=grid.map(()=>~~(Math.random()*Q))}});add('slider',{label:'Température T ×10',min:2,max:30,val:6,fn:v=>T=v/10});add('btn',{label:'Reset',ghost:true,fn:()=>grid=grid.map(()=>~~(Math.random()*Q))});
function loop(){const N=cols*rows;for(let iter=0;iter<N*2;iter++){const i=~~(Math.random()*N),x=i%cols,y=~~(i/cols),s=grid[i],ns=~~(Math.random()*Q);if(s===ns)continue;let dE=0;[[0,1],[-1,0],[0,-1],[1,0]].forEach(([dx,dy])=>{const nb=grid[((y+dy+rows)%rows)*cols+(x+dx+cols)%cols];dE+=(nb===s?1:0)-(nb===ns?1:0)});if(dE<=0||Math.random()<Math.exp(-dE/T))grid[i]=ns}step++;const pal=Array.from({length:Q},(_,k)=>{const h=k/Q;return[~~(127+120*Math.cos(6.283*h)),~~(127+120*Math.cos(6.283*(h+.33))),~~(127+120*Math.cos(6.283*(h+.67)))]});renderScaled(canvas,ctx,S,(d,w,h)=>{for(let y=0;y<h;y++)for(let x=0;x<w;x++){const c=pal[grid[Math.min(rows-1,y)*cols+Math.min(cols-1,x)]],o=(y*w+x)*4;d[o]=c[0];d[o+1]=c[1];d[o+2]=c[2];d[o+3]=255}});const ci=document.getElementById('canvas-info');if(ci)ci.textContent=`Q=${Q}  T=${T.toFixed(1)}  (Tc ≈ ${(1/Math.log(1+Math.sqrt(Q))).toFixed(2)})  balayage ${step}`;raf=expRAF(loop)}loop()}};

/* ── 84 : Thomas Attractor ── */
EXPS.thomas={tag:'Mathématiques · Chaos',title:'Attracteur de Thomas',hint:'',
info:'<strong>René Thomas</strong> (1999) : ẋ=sin(y)−bx, ẏ=sin(z)−by, ż=sin(x)−bz. Pour b < 0.208 : chaos. b = 0 : conservatif. b entre 0 et 0.2 : attracteurs étranges avec auto-similitude à toutes les échelles.',
preview(c,g){g.fillStyle='#080810';g.fillRect(0,0,c.width,c.height);let x=.1,y=0,z=0;const b=.19,dt=.05;g.strokeStyle='#5230cc';g.lineWidth=.5;g.beginPath();let f=true;for(let i=0;i<12000;i++){const dx=Math.sin(y)-b*x,dy=Math.sin(z)-b*y,dz=Math.sin(x)-b*z;x+=dx*dt;y+=dy*dt;z+=dz*dt;const px=(x+4)/8*c.width,py=(y+4)/8*c.height;f?(g.moveTo(px,py),f=false):g.lineTo(px,py)}g.stroke()},
setup(canvas,ctx,add){let b=.19,view='xy';
const A=attractor(canvas,ctx,{deriv:([x,y,z])=>[Math.sin(y)-b*x,Math.sin(z)-b*y,Math.sin(x)-b*z],p0:[.1,0,0],dt:.06,steps:30,proj:q=>view==='xy'?[q[0],q[1]]:view==='xz'?[q[0],q[2]]:[(q[0]-q[1])*.7,q[2]-(q[0]+q[1])*.4],colors:['#8060f0','#e09030']});
add('slider',{label:'b ×1000',min:100,max:300,val:190,fn:v=>{b=v/1000;A.reset()}});add('btn',{label:'Vue XY',ghost:true,fn:()=>{view='xy';A.reset()}});add('btn',{label:'Vue XZ',ghost:true,fn:()=>{view='xz';A.reset()}});add('btn',{label:'Vue 3D',ghost:true,fn:()=>{view='iso';A.reset()}});add('btn',{label:'Reset',ghost:true,fn:()=>A.reset()});
function loop(){A.frame();const ci=document.getElementById('canvas-info');if(ci)ci.textContent=`b=${b.toFixed(3)} — ${b<.208?'chaos':'orbite périodique / point fixe'} — étape ${A.steps.toLocaleString()}`;raf=expRAF(loop)}A.reset();loop()}};

/* ── 85 : SPH Fluid ── */
EXPS.sph={tag:'Physique · Fluides',title:'Simulation de Fluide (SPH)',hint:'Maintenez le clic pour verser du liquide',
info:'<strong>Fluide à particules</strong> : chaque particule mesure la densité de ses voisines dans un rayon h et les repousse si elles sont trop serrées (méthode de relaxation de double densité de Clavet, Beaudoin et Poulin, 2005, cousine de la SPH de Lucy et Gingold, 1977). Sans aucune grille, on obtient un liquide quasi incompressible : vagues, éclaboussures et surface libre émergent seules. Technique utilisée en effets spéciaux et dans les jeux vidéo.',
preview(c,g){const W=c.width,H=c.height;g.fillStyle='#080810';g.fillRect(0,0,W,H);const pts=Array.from({length:80},()=>({x:Math.random()*W*.6+W*.2,y:Math.random()*H*.5+H*.1,vx:(Math.random()-.5)*2,vy:0}));for(let t=0;t<30;t++){pts.forEach(p=>{p.vy+=.3;p.x+=p.vx;p.y+=p.vy;if(p.y>H){p.y=H;p.vy*=-.5;p.vx+=(Math.random()-.5)*.5}if(p.x<0||p.x>W)p.vx*=-1})}pts.forEach(p=>{const spd=Math.sqrt(p.vx*p.vx+p.vy*p.vy);g.fillStyle=`hsl(${200+spd*10},75%,${50+spd*5}%)`;g.beginPath();g.arc(p.x,p.y,3,0,Math.PI*2);g.fill()})},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height,h=16,rho0=6,kP=.06,kNear=.18,MAX=900;let g=.18,P=[],pour=0,mx=W/2,my=H*.15,held=false;
function add1(x,y,vx=0,vy=0){if(P.length<MAX)P.push({x,y,px:x,py:y,vx,vy})}
function block(x0,y0,w,hh){for(let y=y0;y<y0+hh;y+=7)for(let x=x0;x<x0+w;x+=7)add1(x+Math.random(),y+Math.random())}
function reset(){P=[];block(W*.08,H*.25,W*.3,H*.65)}reset();
canvas.onmousedown=e=>{held=true;mv(e)};canvas.onmouseup=canvas.onmouseleave=()=>held=false;canvas.onmousemove=e=>mv(e);function mv(e){mx=e.offsetX/canvas.offsetWidth*W;my=e.offsetY/canvas.offsetHeight*H}
add('btn',{label:'Barrage',fn:reset});add('btn',{label:'Goutte',ghost:true,fn:()=>{for(let a=0;a<120;a++){const r=Math.sqrt(Math.random())*34,t=Math.random()*6.283;add1(W*.6+r*Math.cos(t),H*.15+r*Math.sin(t),0,1)}}});add('btn',{label:'Vider',ghost:true,fn:()=>P=[]});add('slider',{label:'Gravité ×100',min:0,max:40,val:18,fn:v=>g=v/100});
const cell=h,gw=Math.ceil(W/cell)+1,gh=Math.ceil(H/cell)+1;let buckets=Array.from({length:gw*gh},()=>[]);
function step(){if(held&&P.length<MAX)for(let k=0;k<3;k++)add1(mx+(Math.random()-.5)*10,my+(Math.random()-.5)*10,0,1.5);
for(const p of P){p.vy+=g;p.px=p.x;p.py=p.y;p.x+=p.vx;p.y+=p.vy}
for(const b of buckets)b.length=0;for(const p of P){const cx=Math.max(0,Math.min(gw-1,~~(p.x/cell))),cy=Math.max(0,Math.min(gh-1,~~(p.y/cell)));buckets[cy*gw+cx].push(p)}
for(const p of P){const cx=~~(p.x/cell),cy=~~(p.y/cell);let rho=0,rhoN=0;const nb=[];for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const X=cx+dx,Y=cy+dy;if(X<0||Y<0||X>=gw||Y>=gh)continue;for(const o of buckets[Y*gw+X]){if(o===p)continue;const rx=o.x-p.x,ry=o.y-p.y,r2=rx*rx+ry*ry;if(r2<h*h){const r=Math.sqrt(r2)||.01,q=1-r/h;rho+=q*q;rhoN+=q*q*q;nb.push(o,rx/r,ry/r,q)}}}
const pr=kP*(rho-rho0),prN=kNear*rhoN;let dxp=0,dyp=0;for(let i=0;i<nb.length;i+=4){const o=nb[i],ux=nb[i+1],uy=nb[i+2],q=nb[i+3],D=(pr*q+prN*q*q)*.5;o.x+=D*ux;o.y+=D*uy;dxp-=D*ux;dyp-=D*uy}p.x+=dxp;p.y+=dyp}
for(const p of P){if(p.x<4)p.x=4;if(p.x>W-4)p.x=W-4;if(p.y<4)p.y=4;if(p.y>H-4)p.y=H-4;p.vx=(p.x-p.px)*.995;p.vy=(p.y-p.py)*.995}}
function loop(){step();step();ctx.fillStyle='#080810';ctx.fillRect(0,0,W,H);for(const p of P){const s=Math.min(1,Math.hypot(p.vx,p.vy)/5);ctx.fillStyle=`hsl(${210-s*30},85%,${45+s*30}%)`;ctx.beginPath();ctx.arc(p.x,p.y,4.2,0,Math.PI*2);ctx.fill()}const ci=document.getElementById('canvas-info');if(ci)ci.textContent=`${P.length} particules · maintenez le clic pour verser`;raf=expRAF(loop)}loop()}};

/* ── 86 : Complex Plane Transformations ── */
EXPS.zplane={tag:'Mathématiques · Traitement du Signal',title:'Plan Complexe et Transformations',hint:'',
info:'<strong>Fonctions holomorphes</strong> : une fonction f: ℂ→ℂ conforme (préserve les angles) transforme les lignes de grille en courbes douces. f(z)=z² double les angles, e^z convertit les rectangles en spirales, sin(z) replie le plan.',
preview(c,g){const W=c.width,H=c.height,img=g.createImageData(W,H);for(let py=0;py<H;py++)for(let px=0;px<W;px++){const zr=(px/W)*4-2,zi=(py/H)*4-2;const wr=zr*zr-zi*zi,wi=2*zr*zi;const u=(wr%1+1)%1,v=(wi%1+1)%1;const idx=(py*W+px)*4;img.data[idx]=~~((Math.sin(wr*Math.PI)*.5+.5)*200);img.data[idx+1]=~~((Math.sin(wi*Math.PI)*.5+.5)*180);img.data[idx+2]=~~(u*v*220);img.data[idx+3]=255}g.putImageData(img,0,0)},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height;let fn='square',t=0,animated=false,zoom=2;add('btn',{label:'z²',fn:()=>{fn='square';if(!animated)draw()}});add('btn',{label:'e^z',ghost:true,fn:()=>{fn='exp';if(!animated)draw()}});add('btn',{label:'sin(z)',ghost:true,fn:()=>{fn='sin';if(!animated)draw()}});add('btn',{label:'1/z',ghost:true,fn:()=>{fn='inv';if(!animated)draw()}});add('btn',{label:'z+1/z',ghost:true,fn:()=>{fn='joukowski';if(!animated)draw()}});const ab=add('btn',{label:'▶ Animer',ghost:true,fn:()=>{animated=!animated;ab.textContent=animated?'⏸ Stop':'▶ Animer';if(animated)loop()}});
const img=ctx.createImageData(W,H);function applyFn(zr,zi){if(fn==='square')return[zr*zr-zi*zi,2*zr*zi];if(fn==='exp'){const er=Math.exp(zr);return[er*Math.cos(zi),er*Math.sin(zi)]}if(fn==='sin'){return[Math.sin(zr)*Math.cosh(zi),Math.cos(zr)*Math.sinh(zi)]}if(fn==='inv'){const d=zr*zr+zi*zi||.0001;return[zr/d,-zi/d]}if(fn==='joukowski'){const d=zr*zr+zi*zi||.0001;return[zr+zr/d,zi-zi/d]}return[zr,zi]}
function draw(){for(let py=0;py<H;py++)for(let px=0;px<W;px++){const zr=(px/W)*zoom*2-zoom+t*.1,zi=(py/H)*zoom*2-zoom;const[wr,wi]=applyFn(zr,zi);const gridR=Math.abs(Math.sin(wr*Math.PI)),gridI=Math.abs(Math.sin(wi*Math.PI));const idx=(py*W+px)*4;img.data[idx]=~~(gridR*gridI*50+(1-gridR)*(1-gridI)*200);img.data[idx+1]=~~(gridR*200);img.data[idx+2]=~~(gridI*220);img.data[idx+3]=255}ctx.putImageData(img,0,0)}function loop(){if(!animated)return;t+=.02;draw();raf=expRAF(loop)}draw()}};

/* ── 87 : ACO Ants ── */
EXPS.aco={tag:'Biologie · Intelligence Collective',title:'Colonie de Fourmis (ACO)',hint:'Cliquez pour déplacer la nourriture',
info:'<strong>ACO</strong> (Ant Colony Optimization, Dorigo 1992) : les fourmis déposent des phéromones sur leur chemin. Les chemins courts s\'évaporent moins vite et attirent plus de fourmis — convergence vers l\'optimal sans coordination centrale.',
preview(c,g){const W=c.width,H=c.height;g.fillStyle='#080810';g.fillRect(0,0,W,H);const nest={x:W*.15,y:H*.5},food={x:W*.85,y:H*.5};g.fillStyle='#d63f0e';g.beginPath();g.arc(nest.x,nest.y,10,0,Math.PI*2);g.fill();g.fillStyle='#2aaa7a';g.beginPath();g.arc(food.x,food.y,10,0,Math.PI*2);g.fill();for(let i=0;i<80;i++){const t=Math.random(),zig=Math.sin(t*Math.PI*4)*(1-t)*30;g.strokeStyle=`rgba(224,144,48,${Math.random()*.4+.1})`;g.lineWidth=.5;g.beginPath();g.moveTo(nest.x,nest.y);g.quadraticCurveTo(W*.5,H/2+zig,food.x,food.y);g.stroke()}},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height;const nest={x:W*.12,y:H*.5},food={x:W*.88,y:H*.5};const PS=3,pw=~~(W/PS),ph_=~~(H/PS);let pheromones=new Float32Array(pw*ph_),ants=[],evaporation=.99,N_ants=60,step=0;canvas.onclick=e=>{food.x=e.offsetX/canvas.offsetWidth*W;food.y=e.offsetY/canvas.offsetHeight*H};function initAnts(){ants=Array.from({length:N_ants},()=>({x:nest.x,y:nest.y,vx:Math.random()*4-2,vy:Math.random()*4-2,hasFood:false,trail:[]}))}initAnts();add('slider',{label:'Évaporation',min:90,max:100,val:99,fn:v=>evaporation=v/100});add('slider',{label:'Fourmis',min:10,max:120,val:N_ants,fn:v=>{N_ants=v;initAnts()}});add('btn',{label:'Reset',ghost:true,fn:()=>{pheromones.fill(0);initAnts()}});
function loop(){// Evaporate
for(let i=0;i<pheromones.length;i++)pheromones[i]*=evaporation;// Move ants
ants.forEach(a=>{const target=a.hasFood?nest:food;const dx=target.x-a.x,dy=target.y-a.y,d=Math.sqrt(dx*dx+dy*dy);// Random walk biased by pheromones
const baseAngle=Math.atan2(dy,dx);let px=~~(a.x/PS),py=~~(a.y/PS);if(px>=0&&px<pw&&py>=0&&py<ph_){const ph=pheromones[py*pw+px];a.vx=a.vx*.7+dx/d*.3+ph*Math.cos(baseAngle)*.5+(Math.random()-.5)*.5;a.vy=a.vy*.7+dy/d*.3+ph*Math.sin(baseAngle)*.5+(Math.random()-.5)*.5}const spd=Math.sqrt(a.vx*a.vx+a.vy*a.vy);a.vx=a.vx/spd*3.5;a.vy=a.vy/spd*3.5;a.x+=a.vx;a.y+=a.vy;if(a.x<0)a.x=0;if(a.x>=W)a.x=W-1;if(a.y<0)a.y=0;if(a.y>=H)a.y=H-1;// Deposit pheromone
const ix=~~(a.x/PS),iy=~~(a.y/PS);if(ix>=0&&ix<pw&&iy>=0&&iy<ph_)pheromones[iy*pw+ix]+=a.hasFood?.6:.25;// Check targets
if(Math.hypot(a.x-food.x,a.y-food.y)<12){a.hasFood=true}if(Math.hypot(a.x-nest.x,a.y-nest.y)<12&&a.hasFood){a.hasFood=false}});step++;// Draw pheromones
renderScaled(canvas,ctx,PS,(d,w,h)=>{for(let y=0;y<h;y++)for(let x=0;x<w;x++){const v=Math.min(1,pheromones[Math.min(ph_-1,y)*pw+Math.min(pw-1,x)]*1.5),o=(y*w+x)*4;d[o]=8+v*210;d[o+1]=8+v*140;d[o+2]=16;d[o+3]=255}});// Draw ants
ants.forEach(a=>{ctx.fillStyle=a.hasFood?'#2aaa7a':'#e09030';ctx.beginPath();ctx.arc(a.x,a.y,2,0,Math.PI*2);ctx.fill()});// Nest & food
ctx.fillStyle='#d63f0e';ctx.beginPath();ctx.arc(nest.x,nest.y,12,0,Math.PI*2);ctx.fill();ctx.fillStyle='#2aaa7a';ctx.beginPath();ctx.arc(food.x,food.y,12,0,Math.PI*2);ctx.fill();raf=expRAF(loop)}loop()}};

/* ── 88 : Spherical Geodesics ── */
EXPS.geodesic={tag:'Mathématiques · Géométrie Différentielle',title:'Géodésiques sur la Sphère',hint:'Glissez pour faire tourner la sphère',
info:'<strong>Géodésique</strong> : sur une sphère, le plus court chemin entre deux points est un arc de grand cercle. La somme des angles d\'un triangle sphérique dépasse 180° de l\'excès sphérique E = A+B+C−π = Aire/R².',
preview(c,g){const W=c.width,H=c.height;g.fillStyle='#080810';g.fillRect(0,0,W,H);const cx=W/2,cy=H/2,R=Math.min(W,H)*.38;g.strokeStyle='rgba(240,237,230,.15)';g.lineWidth=.8;for(let i=0;i<12;i++){const phi=i/12*Math.PI,t=Date.now()*.0001;g.beginPath();for(let j=0;j<=60;j++){const theta=j/60*Math.PI*2;const x=R*Math.sin(phi)*Math.cos(theta),y=R*Math.sin(phi)*Math.sin(theta),z=R*Math.cos(phi);g.lineTo(cx+x*.8-z*.2,cy-y*.7-z*.2)}g.stroke()}const geodesics=[[0,0,Math.PI/3,Math.PI/2],[Math.PI/4,0,Math.PI/2,Math.PI],[0,Math.PI/2,Math.PI/3,Math.PI*1.5]];geodesics.forEach(([phi1,theta1,phi2,theta2])=>{const p1={x:Math.sin(phi1)*Math.cos(theta1),y:Math.sin(phi1)*Math.sin(theta1),z:Math.cos(phi1)};const p2={x:Math.sin(phi2)*Math.cos(theta2),y:Math.sin(phi2)*Math.sin(theta2),z:Math.cos(phi2)};g.strokeStyle='#d63f0e';g.lineWidth=1.5;g.beginPath();for(let t=0;t<=40;t++){const s=t/40,dot=p1.x*p2.x+p1.y*p2.y+p1.z*p2.z,omega=Math.acos(Math.max(-1,Math.min(1,dot)));const f=Math.abs(Math.sin(omega))<.001?s:Math.sin(s*omega)/Math.sin(omega);const g2=Math.abs(Math.sin(omega))<.001?(1-s):Math.sin((1-s)*omega)/Math.sin(omega);const px=R*(f*p2.x+g2*p1.x),py=R*(f*p2.y+g2*p1.y),pz=R*(f*p2.z+g2*p1.z);t===0?g.moveTo(cx+px*.8-pz*.2,cy-py*.7-pz*.2):g.lineTo(cx+px*.8-pz*.2,cy-py*.7-pz*.2)}g.stroke()})},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height,cx=W/2,cy=H/2,R=Math.min(W,H)*.4;let rotX=.3,rotY=0,dragging=false,lx,ly,showGrid=true,numGeo=6;canvas.onmousedown=e=>{dragging=true;lx=e.clientX;ly=e.clientY};canvas.onmouseup=()=>dragging=false;canvas.onmouseleave=()=>dragging=false;canvas.onmousemove=e=>{if(!dragging)return;rotY+=(e.clientX-lx)*.01;rotX+=(e.clientY-ly)*.01;lx=e.clientX;ly=e.clientY;draw()};add('btn',{label:'Grille',ghost:true,fn:()=>{showGrid=!showGrid;draw()}});add('slider',{label:'Géodésiques',min:1,max:20,val:6,fn:v=>{numGeo=v;newGeo();draw()}});add('btn',{label:'Nouvelles',ghost:true,fn:()=>{newGeo();draw()}});let geo=[];function rndPt(){const phi=Math.acos(1-2*Math.random()),th=Math.random()*Math.PI*2;return{x:Math.sin(phi)*Math.cos(th),y:Math.cos(phi),z:Math.sin(phi)*Math.sin(th)}}function newGeo(){geo=Array.from({length:numGeo},()=>[rndPt(),rndPt()])}newGeo();let auto=true;add('btn',{label:'Vue Nord',ghost:true,fn:()=>{rotX=0;rotY=0;draw()}});add('btn',{label:'Vue Oblique',ghost:true,fn:()=>{rotX=.4;rotY=.6;draw()}});
function rotPt(px,py,pz){const cx2=Math.cos(rotX),sx=Math.sin(rotX),cy2=Math.cos(rotY),sy=Math.sin(rotY);const y2=py*cx2-pz*sx,z2=py*sx+pz*cx2;const x3=px*cy2+z2*sy,z3=-px*sy+z2*cy2;return{x:x3,y:y2,z:z3}}function project(px,py,pz){const p=rotPt(px,py,pz);return{x:cx+p.x*R,y:cy-p.y*R,d:p.z}}function slerp(p1,p2,t){const dot=Math.max(-1,Math.min(1,p1.x*p2.x+p1.y*p2.y+p1.z*p2.z));const omega=Math.acos(dot);if(Math.abs(Math.sin(omega))<.001)return{x:p1.x,y:p1.y,z:p1.z};const f=Math.sin(t*omega)/Math.sin(omega),g2=Math.sin((1-t)*omega)/Math.sin(omega);return{x:f*p2.x+g2*p1.x,y:f*p2.y+g2*p1.y,z:f*p2.z+g2*p1.z}}
function draw(){ctx.fillStyle='#080810';ctx.fillRect(0,0,W,H);// Sphere outline
const grd=ctx.createRadialGradient(cx-R*.35,cy-R*.35,R*.1,cx,cy,R);grd.addColorStop(0,'#1c2440');grd.addColorStop(1,'#0b0e1c');ctx.fillStyle=grd;ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.fill();ctx.strokeStyle='rgba(240,237,230,.4)';ctx.lineWidth=1;ctx.stroke();if(showGrid){for(let lat=1;lat<6;lat++){const phi=lat/6*Math.PI;ctx.strokeStyle='rgba(240,237,230,.18)';ctx.lineWidth=.7;ctx.beginPath();let first=true;for(let j=0;j<=60;j++){const theta=j/60*Math.PI*2;const pt=project(Math.sin(phi)*Math.cos(theta),Math.cos(phi),Math.sin(phi)*Math.sin(theta));if(pt.d>0){first?ctx.moveTo(pt.x,pt.y):ctx.lineTo(pt.x,pt.y);first=false}}ctx.stroke()}for(let lng=0;lng<12;lng++){const theta=lng/12*Math.PI*2;ctx.beginPath();let first=true;for(let j=0;j<=40;j++){const phi=j/40*Math.PI;const pt=project(Math.sin(phi)*Math.cos(theta),Math.cos(phi),Math.sin(phi)*Math.sin(theta));if(pt.d>0){first?ctx.moveTo(pt.x,pt.y):ctx.lineTo(pt.x,pt.y);first=false}}ctx.stroke()}}// Draw geodesics
for(let g=0;g<geo.length;g++){const[p1,p2]=geo[g];const col=`hsl(${g/geo.length*360},80%,62%)`;for(const front of[false,true]){ctx.strokeStyle=col;ctx.lineWidth=front?2.4:1;ctx.globalAlpha=front?1:.35;ctx.setLineDash(front?[]:[3,4]);ctx.beginPath();let pen=false;for(let t=0;t<=80;t++){const p=slerp(p1,p2,t/80),pt=project(p.x,p.y,p.z);if((pt.d>0)===front){pen?ctx.lineTo(pt.x,pt.y):ctx.moveTo(pt.x,pt.y);pen=true}else pen=false}ctx.stroke()}ctx.setLineDash([]);ctx.globalAlpha=1;for(const p of[p1,p2]){const pt=project(p.x,p.y,p.z);if(pt.d>0){ctx.fillStyle=col;ctx.beginPath();ctx.arc(pt.x,pt.y,4,0,Math.PI*2);ctx.fill()}}}}function spin(){if(auto&&!dragging){rotY+=.004;draw()}raf=expRAF(spin)}canvas.addEventListener('mousedown',()=>auto=false);draw();spin()}};

/* ── 89 : Burning Ship Fractal ── */
EXPS.burningship={tag:'Mathématiques · Fractales',title:'Fractale Burning Ship',hint:'Scroll pour zoomer · Drag pour déplacer',
info:'<strong>Burning Ship</strong> (Michael Michelitsch & Otto Rössler, 1992) : zₙ₊₁ = (|Re(zₙ)| + i|Im(zₙ)|)² + c. L\'ajout des valeurs absolues brise la symétrie de Mandelbrot et crée l\'apparence d\'un vaisseau en flammes.',
preview(c,g){const W=c.width,H=c.height,img=g.createImageData(W,H);for(let py=0;py<H;py++)for(let px=0;px<W;px++){const cr=px/W*3.5-2.5,ci=-(py/H*2-.4);let zr=0,zi=0,n=0;while(zr*zr+zi*zi<=4&&n<80){const nr=zr*zr-zi*zi+cr;zi=Math.abs(2*zr*zi)+ci;zr=Math.abs(nr);n++}const t=n/80,idx=(py*W+px)*4;if(n>=80){img.data[idx]=img.data[idx+1]=img.data[idx+2]=0}else{img.data[idx]=~~(Math.sin(t*Math.PI+.5)*240);img.data[idx+1]=~~(Math.sin(t*Math.PI*2)*120+40);img.data[idx+2]=~~(Math.sin(t*Math.PI*3+2)*200)}img.data[idx+3]=255}g.putImageData(img,0,0)},
setup(canvas,ctx,add){let zoom=180,cx=-0.4,cy=-0.6,maxIter=120,dragging=false,lx,ly;canvas.style.cursor='crosshair';canvas.onmousedown=e=>{dragging=true;lx=e.clientX;ly=e.clientY};canvas.onmouseup=()=>dragging=false;canvas.onmousemove=e=>{if(!dragging)return;cx-=(e.clientX-lx)/zoom;cy-=(e.clientY-ly)/zoom;lx=e.clientX;ly=e.clientY;draw()};canvas.onwheel=e=>{e.preventDefault();const f=e.deltaY<0?1.3:.77;const mx=(e.offsetX-canvas.width/2)/zoom,my=(e.offsetY-canvas.height/2)/zoom;zoom*=f;cx+=mx*(1-1/f);cy+=my*(1-1/f);draw()};add('btn',{label:'Reset',ghost:true,fn:()=>{zoom=180;cx=-0.4;cy=-0.6;draw()}});add('slider',{label:'Itérations',min:40,max:400,val:120,fn:v=>{maxIter=v;draw()}});add('btn',{label:'Vaisseau',ghost:true,fn:()=>{cx=-1.74;cy=-0.028;zoom=2500;draw()}});add('btn',{label:'Flammes',ghost:true,fn:()=>{cx=-1.758;cy=-.016;zoom=8000;draw()}});
function draw(){const W=canvas.width,H=canvas.height,img=ctx.createImageData(W,H);for(let py=0;py<H;py++)for(let px=0;px<W;px++){const cr=(px-W/2)/zoom+cx,ci=-((py-H/2)/zoom+cy);let zr=0,zi=0,n=0;while(zr*zr+zi*zi<=4&&n<maxIter){const nr=zr*zr-zi*zi+cr;zi=Math.abs(2*zr*zi)+ci;zr=Math.abs(nr);n++}const idx=(py*W+px)*4;if(n>=maxIter){img.data[idx]=img.data[idx+1]=img.data[idx+2]=0}else{const t=n/maxIter;img.data[idx]=~~(Math.pow(Math.sin(t*Math.PI),2)*220+30);img.data[idx+1]=~~(Math.pow(Math.sin(t*Math.PI+1),2)*100);img.data[idx+2]=~~(Math.pow(Math.sin(t*Math.PI+2),2)*180)}img.data[idx+3]=255}ctx.putImageData(img,0,0)}draw()}};

/* ── 90 : Evolution Simulation ── */
EXPS.evolution={tag:'Biologie · Évolution',title:'Évolution par Sélection',hint:'Les proies rapides (vertes) survivent mieux aux prédateurs',
info:'<strong>Sélection naturelle</strong> (Darwin, 1859) : les individus les plus aptes survivent et se reproduisent. Vitesse, taille et couleur évoluent vers l\'optimum — adaptation sans concepteur, juste la variation et la sélection.',
preview(c,g){const W=c.width,H=c.height;g.fillStyle='#080810';g.fillRect(0,0,W,H);for(let i=0;i<40;i++){const spd=Math.random()*.8+.2;g.fillStyle=`hsl(${spd*120},70%,55%)`;g.beginPath();g.arc(Math.random()*W,Math.random()*H,spd*5+2,0,Math.PI*2);g.fill()}},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height;let pop=[],pred=[],gen=0,N=60,nPred=3,hist=[];function randomCreature(){const spd=Math.random()*.9+.1,size=Math.random()*.8+.2;return{x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*spd*3,vy:(Math.random()-.5)*spd*3,speed:spd,size,alive:true,age:0}}function initPop(){pop=Array.from({length:N},randomCreature);pred=Array.from({length:nPred},(_,k)=>({x:W*(k+.5)/nPred,y:H*.5,vx:2,vy:1,speed:2.4}));hist=[pop.reduce((s,c)=>s+c.speed,0)/pop.length]}initPop();add('slider',{label:'Prédateurs',min:1,max:6,val:nPred,fn:v=>{nPred=v;initPop();gen=0}});add('btn',{label:'Reset',ghost:true,fn:()=>{initPop();gen=0}});add('slider',{label:'Pop.',min:20,max:120,val:N,fn:v=>{N=v;initPop()}});
function loop(){ctx.fillStyle='rgba(8,8,16,.18)';ctx.fillRect(0,0,W,H);// Move predators
pred.forEach(p=>{p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>W)p.vx*=-1;if(p.y<0||p.y>H)p.vy*=-1;// Chase nearest prey
let target=null,minD=Infinity;pop.filter(c=>c.alive).forEach(c=>{const d=Math.hypot(c.x-p.x,c.y-p.y);if(d<minD){minD=d;target=c}});if(target){const dx=target.x-p.x,dy=target.y-p.y,d=Math.hypot(dx,dy)||1;p.vx=p.vx*.85+dx/d*p.speed*.15;p.vy=p.vy*.85+dy/d*p.speed*.15}// Eat
pop.forEach(c=>{if(c.alive&&Math.hypot(c.x-p.x,c.y-p.y)<12+c.size*8)c.alive=false})});// Move prey
pop.filter(c=>c.alive).forEach(c=>{c.x+=c.vx;c.y+=c.vy;if(c.x<0||c.x>W){c.x=Math.max(0,Math.min(W,c.x));c.vx*=-1}if(c.y<0||c.y>H){c.y=Math.max(0,Math.min(H,c.y));c.vy*=-1}c.age++;// Flee
pred.forEach(p=>{const dx=c.x-p.x,dy=c.y-p.y,d=Math.hypot(dx,dy)||1;if(d<80){c.vx+=dx/d*c.speed*.35;c.vy+=dy/d*c.speed*.35}});const spd=Math.sqrt(c.vx*c.vx+c.vy*c.vy);if(spd>c.speed*3){c.vx=c.vx/spd*c.speed*3;c.vy=c.vy/spd*c.speed*3}});// Draw prey
pop.filter(c=>c.alive).forEach(c=>{const hue=c.speed*120,r=c.size*6+2;ctx.fillStyle=`hsl(${hue},72%,55%)`;ctx.beginPath();ctx.arc(c.x,c.y,r,0,Math.PI*2);ctx.fill()});// Draw predators
pred.forEach(p=>{ctx.fillStyle='#ff2020';ctx.beginPath();ctx.arc(p.x,p.y,12,0,Math.PI*2);ctx.fill();ctx.fillStyle='white';ctx.font='bold 11px monospace';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('▲',p.x,p.y)});// New generation
const alive=pop.filter(c=>c.alive);if(alive.length<N*.5){gen++;hist.push(alive.reduce((s,c)=>s+c.speed,0)/alive.length);if(hist.length>60)hist.shift();const offspring=[];while(offspring.length<N){const parent=alive[~~(Math.random()*alive.length)];const mutStrength=.15;offspring.push({x:parent.x+(Math.random()-.5)*30,y:parent.y+(Math.random()-.5)*30,speed:Math.max(.05,parent.speed+(Math.random()-.5)*mutStrength),size:Math.max(.05,parent.size+(Math.random()-.5)*mutStrength*.5),vx:(Math.random()-.5)*parent.speed*2,vy:(Math.random()-.5)*parent.speed*2,alive:true,age:0})}pop=offspring;pred.forEach(p=>{p.vx=(Math.random()-.5)*p.speed*2;p.vy=(Math.random()-.5)*p.speed*2})}const avgSpd=alive.reduce((s,c)=>s+c.speed,0)/(alive.length||1);ctx.textAlign='left';ctx.textBaseline='alphabetic';if(hist.length>1){const gw=180,gh=60,gx=W-gw-10,gy=H-gh-10;ctx.fillStyle='rgba(8,8,16,.85)';ctx.fillRect(gx-4,gy-16,gw+8,gh+22);ctx.strokeStyle='rgba(240,237,230,.25)';ctx.strokeRect(gx,gy,gw,gh);ctx.strokeStyle='#2aaa7a';ctx.lineWidth=1.6;ctx.beginPath();hist.forEach((v,i)=>{const X=gx+i/(Math.max(1,hist.length-1))*gw,Y=gy+gh-Math.min(1,v/1.6)*gh;i?ctx.lineTo(X,Y):ctx.moveTo(X,Y)});ctx.stroke();ctx.fillStyle='rgba(240,237,230,.75)';ctx.font='10px monospace';ctx.fillText('vitesse moyenne / génération',gx,gy-4)}const ci=document.getElementById('canvas-info');if(ci)ci.textContent=`Gén. ${gen} — vivants: ${alive.length}/${N} — vitesse moy: ${avgSpd.toFixed(2)}`;raf=expRAF(loop)}loop()}};

/* ── 91 : Halftone ── */
EXPS.halftone={tag:'Art Génératif · Optique',title:'Tramage Halftone',hint:'',
info:'<strong>Tramage halftone</strong> : des disques de taille variable simulent des niveaux de gris — la technique de Frederic Ives (1881) utilisée dans toute la presse imprimée. L\'œil intègre spatialement et perçoit une intensité continue.',
preview(c,g){const W=c.width,H=c.height;g.fillStyle='#f4f2ed';g.fillRect(0,0,W,H);const step=12;for(let y=step/2;y<H;y+=step)for(let x=step/2;x<W;x+=step){const dx=x-W/2,dy=y-H/2,d=Math.sqrt(dx*dx+dy*dy),v=Math.max(0,1-d/Math.min(W,H)*.7);g.fillStyle='#111010';g.beginPath();g.arc(x,y,v*step*.48,0,Math.PI*2);g.fill()}},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height;let step=12,pattern='radial',angle=15*Math.PI/180,invertBg=false,t=0,animated=false;add('slider',{label:'Taille grille',min:6,max:25,val:12,fn:v=>{step=v;if(!animated)draw()}});add('slider',{label:'Angle de trame (°)',min:0,max:90,val:15,fn:v=>{angle=v*Math.PI/180;if(!animated)draw()}});add('btn',{label:'Radial',fn:()=>{pattern='radial';if(!animated)draw()}});add('btn',{label:'Onde',ghost:true,fn:()=>{pattern='wave';if(!animated)draw()}});add('btn',{label:'Vortex',ghost:true,fn:()=>{pattern='vortex';if(!animated)draw()}});add('btn',{label:'Inverser',ghost:true,fn:()=>{invertBg=!invertBg;if(!animated)draw()}});const ab=add('btn',{label:'▶ Animer',ghost:true,fn:()=>{animated=!animated;ab.textContent=animated?'⏸ Stop':'▶ Animer';if(animated)loop()}});
function getValue(x,y){const dx=x-W/2,dy=y-H/2,d=Math.sqrt(dx*dx+dy*dy);if(pattern==='radial')return Math.max(0,1-d/Math.min(W,H)*.75);if(pattern==='wave')return(Math.sin(d*.08+t)*.5+.5)*(1-d/Math.min(W,H)*.8);if(pattern==='vortex'){const a=Math.atan2(dy,dx);return(Math.sin(a*4+d*.05+t)*.5+.5)*(1-d/Math.min(W,H)*.7)}return.5}function draw(){const ca=Math.cos(angle),sa=Math.sin(angle),cx=W/2,cy=H/2,R=Math.hypot(W,H)/2+step;ctx.fillStyle=invertBg?'#111010':'#f4f2ed';ctx.fillRect(0,0,W,H);ctx.fillStyle=invertBg?'#f4f2ed':'#111010';ctx.beginPath();for(let v=-R;v<=R;v+=step)for(let u=-R;u<=R;u+=step){const x=cx+u*ca-v*sa,y=cy+u*sa+v*ca;if(x<-step||y<-step||x>W+step||y>H+step)continue;const r=Math.max(0,getValue(x,y))*step*.55;if(r<.2)continue;ctx.moveTo(x+r,y);ctx.arc(x,y,r,0,Math.PI*2)}ctx.fill()}function loop(){if(!animated)return;t+=.04;draw();raf=expRAF(loop)}draw()}};

/* ── 92 : XOR CA / Sierpinski ── */
EXPS.xorca={tag:'Informatique · Automates',title:'Automate XOR et Sierpinski',hint:'',
info:'<strong>Automate XOR</strong> : la valeur d\'une cellule = XOR de ses voisins de gauche et de droite. Sur une rangée initiale avec une seule cellule allumée, le triangle de Sierpinski émerge — connexion profonde entre arithmétique de Pascal et géométrie fractale.',
preview(c,g){const W=c.width,H=c.height,S=2,cols=~~(W/S),rows=~~(H/S);g.fillStyle='#080810';g.fillRect(0,0,W,H);let row=new Uint8Array(cols);row[~~(cols/2)]=1;for(let y=0;y<rows;y++){for(let x=0;x<cols;x++)if(row[x]){g.fillStyle=`hsl(${x/cols*360},75%,55%)`;g.fillRect(x*S,y*S,S,S)}const next=new Uint8Array(cols);for(let x=0;x<cols;x++)next[x]=row[(x-1+cols)%cols]^row[(x+1)%cols];row=next}},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height,S=2,cols=~~(W/S),rows=~~(H/S);let rainbow=true,multi=false,step=0;let row=new Uint8Array(cols);function init(){row.fill(0);row[~~(cols/2)]=1;step=0;ctx.fillStyle='#080810';ctx.fillRect(0,0,W,H)}init();add('btn',{label:'Arc-en-ciel',fn:()=>{rainbow=true;init()}});add('btn',{label:'Blanc',ghost:true,fn:()=>{rainbow=false;init()}});add('btn',{label:'Multi-graine',ghost:true,fn:()=>{init();for(let i=0;i<5;i++)row[~~(Math.random()*cols)]=1}});add('btn',{label:'Reset',ghost:true,fn:init});function loop(){if(step>=rows){ctx.fillStyle='rgba(8,8,16,.003)';ctx.fillRect(0,0,W,H);init();return}for(let x=0;x<cols;x++)if(row[x]){ctx.fillStyle=rainbow?`hsl(${x/cols*360},75%,55%)`:'rgba(240,237,230,.9)';ctx.fillRect(x*S,step*S,S,S)}const next=new Uint8Array(cols);for(let x=0;x<cols;x++)next[x]=row[(x-1+cols)%cols]^row[(x+1)%cols];row=next;step++;const ci=document.getElementById('canvas-info');if(ci)ci.textContent=`Génération ${step} / ${rows}`;raf=expRAF(loop)}loop()}};

/* ── 93 : Oscillon ── */
EXPS.oscillon={tag:'Physique · Sable Vibrant',title:'Oscillons — Sable Vibrant',hint:'Cliquez pour créer une impulsion',
info:'<strong>Ondes de Faraday et oscillons</strong> : une couche de sable ou de liquide secouée verticalement (ici, une membrane dont la tension est modulée à la fréquence Ω) répond à Ω/2. Au-dessus d\'un seuil de forçage ε, les ondes de longueur λ = 4πc/Ω s\'amplifient et forment des carrés ou des rayures. Juste au niveau du seuil, des paquets localisés oscillent sur place : ce sont les oscillons observés par Umbanhowar, Melo et Swinney (1996).',
preview(c,g){renderScaled(c,g,2,(d,N,M)=>{let u=new Float32Array(N*M),v=new Float32Array(N*M),nu=new Float32Array(N*M);[[N*.3,M*.5],[N*.7,M*.5],[N*.5,M*.3],[N*.5,M*.7]].forEach(([cx,cy])=>{for(let y=0;y<M;y++)for(let x=0;x<N;x++){const dd=((x-cx)**2+(y-cy)**2)*4;u[y*N+x]+=1.5*Math.exp(-dd/80)*Math.cos(Math.sqrt(dd)*.5)}});for(let it=0;it<100;it++){for(let y=1;y<M-1;y++)for(let x=1;x<N-1;x++){const idx=y*N+x,lap=(u[idx-1]+u[idx+1]+u[idx-N]+u[idx+N]-4*u[idx])/4;nu[idx]=u[idx]+v[idx]*.05+(-.1*u[idx]+.5*lap-.02*u[idx]*u[idx]*u[idx])*.05;v[idx]+=nu[idx]-u[idx]}[u,nu]=[nu,u]}for(let i=0;i<N*M;i++){const v2=Math.max(-1,Math.min(1,u[i])),n=(v2+1)/2,idx=i*4;d[idx]=~~(n*200);d[idx+1]=~~(n*n*180);d[idx+2]=~~((1-n)*200+50);d[idx+3]=255}})},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height,S=4,gw=~~(W/S),gh=~~(H/S),N=gw*gh;let u=new Float32Array(N),v=new Float32Array(N),eps=.45,lambda=12,t=0;const gamma=.05,kappa=1.5,dt=.35;
function bump(cx,cy,a=.9,r=5){for(let y=Math.max(1,cy-3*r);y<Math.min(gh-1,cy+3*r);y++)for(let x=Math.max(1,cx-3*r);x<Math.min(gw-1,cx+3*r);x++){const d2=(x-cx)**2+(y-cy)**2;u[y*gw+x]+=a*Math.exp(-d2/(r*r))}}
canvas.onclick=e=>bump(~~(e.offsetX/canvas.offsetWidth*gw),~~(e.offsetY/canvas.offsetHeight*gh));
add('slider',{label:'ε forçage ×100',min:0,max:90,val:45,fn:v=>eps=v/100});add('slider',{label:'Longueur d\'onde',min:8,max:24,val:lambda,fn:v=>lambda=v});
add('btn',{label:'Multi-oscillons',fn:()=>{u.fill(0);v.fill(0);[[.25,.5],[.75,.5],[.5,.25],[.5,.75],[.5,.5]].forEach(([a,b])=>bump(~~(gw*a),~~(gh*b)))}});add('btn',{label:'Bruit',ghost:true,fn:()=>{for(let i=0;i<N;i++)u[i]+=(Math.random()-.5)*.05}});add('btn',{label:'Reset',ghost:true,fn:()=>{u.fill(0);v.fill(0)}});
[[.3,.5],[.7,.5]].forEach(([a,b])=>bump(~~(gw*a),~~(gh*b)));
function loop(){const k=2*Math.PI/lambda,Om=2*k;for(let s=0;s<3;s++){const f=1+eps*Math.cos(Om*t);for(let y=1;y<gh-1;y++)for(let x=1;x<gw-1;x++){const i=y*gw+x,lap=u[i-1]+u[i+1]+u[i-gw]+u[i+gw]-4*u[i];v[i]+=(f*lap-gamma*v[i]-kappa*u[i]*u[i]*u[i])*dt}for(let i=0;i<N;i++)u[i]+=v[i]*dt;t+=dt}
let m=0;renderScaled(canvas,ctx,S,(d,w,h)=>{for(let y=0;y<h;y++)for(let x=0;x<w;x++){const val=u[Math.min(gh-1,y)*gw+Math.min(gw-1,x)],a=Math.min(1,Math.abs(val)*1.6),o=(y*w+x)*4;if(Math.abs(val)>m)m=Math.abs(val);if(val>0){d[o]=10+a*240;d[o+1]=10+a*190;d[o+2]=20+a*60}else{d[o]=10+a*110;d[o+1]=10+a*60;d[o+2]=20+a*220}d[o+3]=255}});
const thr=2*gamma/k;const ci=document.getElementById('canvas-info');if(ci)ci.textContent=`ε=${eps.toFixed(2)} (seuil ≈ ${thr.toFixed(2)}) — ${eps>thr?'instable : les motifs croissent':'stable : les impulsions s\'amortissent'} · clic : impulsion`;raf=expRAF(loop)}loop()}};

/* ── 94 : Phase Space Portrait ── */
EXPS.phasespace={tag:'Mathématiques · Systèmes Dynamiques',title:'Portrait de Phase',hint:'Cliquez pour lancer une trajectoire',
info:'<strong>Portrait de phase</strong> : chaque état du système est un point dans l\'espace (x, ẋ). Les trajectoires ne peuvent pas se croiser. Points fixes (attracteurs/répulseurs), cycles limites et séparatrices révèlent toute la dynamique.',
preview(c,g){const W=c.width,H=c.height;g.fillStyle='#080810';g.fillRect(0,0,W,H);const systems=[{name:'pendule',f:(x,v)=>[-Math.sin(x)*.8,v]},{name:'van der pol',f:(x,v)=>[(1-x*x)*v-x*.5,v]}];const cols=['#5230cc','#d63f0e','#2aaa7a'];for(let i=-10;i<=10;i++)for(let j=-10;j<=10;j++){const x=i/10*Math.PI*2,v=j/10*3;const[dx,dv]=systems[0].f(x,v);const mag=Math.sqrt(dx*dx+dv*dv)+.001,px=W/2+i/10*W*.46,py=H/2-j/10*H*.46,l=8;g.strokeStyle=`rgba(82,48,204,${Math.min(.6,mag*.3)})`;g.lineWidth=.7;g.beginPath();g.moveTo(px-dx/mag*l*.5,py+dv/mag*l*.5);g.lineTo(px+dx/mag*l*.5,py-dv/mag*l*.5);g.stroke()}},
setup(canvas,ctx,add){const W=canvas.width,H=canvas.height;let sysName='pendulum',gamma=0.1,trajectories=[],t=0;const systems={pendulum:{f:(x,v)=>[v,-Math.sin(x)-gamma*v],xRange:[-Math.PI*1.8,Math.PI*1.8],vRange:[-4,4],label:'Pendule amorti'},vanderpol:{f:(x,v)=>[v,(1-x*x)*v-x],xRange:[-3.5,3.5],vRange:[-5,5],label:'Van der Pol'},duffing:{f:(x,v)=>[v,x-x*x*x-gamma*v],xRange:[-2.5,2.5],vRange:[-2.5,2.5],label:'Duffing'},linear:{f:(x,v)=>[v,-x-gamma*v],xRange:[-3,3],vRange:[-3,3],label:'Oscillateur linéaire'}};add('btn',{label:'Pendule',fn:()=>{sysName='pendulum';seedTraj()}});add('btn',{label:'Van der Pol',ghost:true,fn:()=>{sysName='vanderpol';seedTraj()}});add('btn',{label:'Duffing',ghost:true,fn:()=>{sysName='duffing';seedTraj()}});add('btn',{label:'Linéaire',ghost:true,fn:()=>{sysName='linear';seedTraj()}});add('slider',{label:'Amortissement γ',min:0,max:30,val:10,fn:v=>{gamma=v*.01;seedTraj()}});add('btn',{label:'Effacer traj.',ghost:true,fn:()=>{trajectories=[];drawField()}});
canvas.onclick=e=>{const sys=systems[sysName];const x=sys.xRange[0]+(e.offsetX/canvas.offsetWidth)*(sys.xRange[1]-sys.xRange[0]);const v=sys.vRange[0]+(1-e.offsetY/canvas.offsetHeight)*(sys.vRange[1]-sys.vRange[0]);trajectories.push({pts:[{x,v}],col:`hsl(${Math.random()*360},75%,55%)`})};function toScreen(x,v){const sys=systems[sysName];return{px:W*.05+(x-sys.xRange[0])/(sys.xRange[1]-sys.xRange[0])*W*.9,py:H*.95-(v-sys.vRange[0])/(sys.vRange[1]-sys.vRange[0])*H*.9}}function drawField(){ctx.fillStyle='#080810';ctx.fillRect(0,0,W,H);const sys=systems[sysName];// Grid
ctx.strokeStyle='rgba(240,237,230,.07)';ctx.lineWidth=.5;for(let i=0;i<=10;i++){const xi=sys.xRange[0]+i/10*(sys.xRange[1]-sys.xRange[0]);const{px}=toScreen(xi,0);ctx.beginPath();ctx.moveTo(px,0);ctx.lineTo(px,H);ctx.stroke();const vi=sys.vRange[0]+i/10*(sys.vRange[1]-sys.vRange[0]);const{py}=toScreen(0,vi);ctx.beginPath();ctx.moveTo(0,py);ctx.lineTo(W,py);ctx.stroke()}// Axes
const orig=toScreen(0,0);ctx.strokeStyle='rgba(240,237,230,.2)';ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(orig.px,0);ctx.lineTo(orig.px,H);ctx.stroke();ctx.beginPath();ctx.moveTo(0,orig.py);ctx.lineTo(W,orig.py);ctx.stroke();// Vector field
for(let i=0;i<=16;i++)for(let j=0;j<=12;j++){const x=sys.xRange[0]+i/16*(sys.xRange[1]-sys.xRange[0]);const v=sys.vRange[0]+j/12*(sys.vRange[1]-sys.vRange[0]);const[dx,dv]=sys.f(x,v);const mag=Math.sqrt(dx*dx+dv*dv)+.001;const{px,py}=toScreen(x,v);const l=Math.min(15,mag*8)/mag*Math.min(1,mag);ctx.strokeStyle=`rgba(150,130,255,${Math.min(.8,.35+mag*.1)})`;ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(px-dx/mag*l*.4,py+dv/mag*l*.4);ctx.lineTo(px+dx/mag*l*.6,py-dv/mag*l*.6);ctx.stroke()}}drawField();
function seedTraj(){const sys=systems[sysName];trajectories=[];for(let k=0;k<4;k++){const x=sys.xRange[0]+(.15+.7*Math.random())*(sys.xRange[1]-sys.xRange[0]),v=sys.vRange[0]+(.15+.7*Math.random())*(sys.vRange[1]-sys.vRange[0]);trajectories.push({pts:[{x,v}],col:`hsl(${k*90+20},80%,60%)`})}}seedTraj();
function loop(){drawField();trajectories.forEach(tr=>{// Integrate
for(let s=0;s<8;s++){const last=tr.pts[tr.pts.length-1];const sys=systems[sysName];const[dx,dv]=sys.f(last.x,last.v);tr.pts.push({x:last.x+dx*.02,v:last.v+dv*.02})}if(tr.pts.length>900)tr.pts=tr.pts.slice(-900);// Draw
if(tr.pts.length>1){ctx.strokeStyle=tr.col;ctx.lineWidth=1.5;ctx.beginPath();tr.pts.forEach(({x,v},i)=>{const{px,py}=toScreen(x,v);i===0?ctx.moveTo(px,py):ctx.lineTo(px,py)});ctx.stroke()}const last=tr.pts[tr.pts.length-1];const{px,py}=toScreen(last.x,last.v);ctx.fillStyle=tr.col;ctx.beginPath();ctx.arc(px,py,4,0,Math.PI*2);ctx.fill()});raf=expRAF(loop)}loop()}};
